INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 9, 'theory', 'Quiz: Python and Rust types');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 9, 0, 'What does −7 / 2 give for integers in Rust?', '["−4, as in Python", "−3: division rounds toward zero", "−3.5", "a compile error"]', 1, 'Python rounds down (−4), Rust rounds toward zero (−3); the remainder −7 % 2 in Rust is −1. For the Python behavior there are div_euclid and rem_euclid.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 9, 1, 'How does a list of a million numbers in Python compare to a Vec<i32> in Rust?', '["the list holds pointers to separate objects, the vector holds the numbers in a row", "both structures store the numbers in a row", "in Rust the vector stores pointers, in Python the numbers", "there is no difference"]', 0, 'Because of this, the vector works better with the CPU cache and takes several times less memory.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 9, 2, 'What do you need to do to add an i32 and an f64?', '["just add them: Rust converts on its own", "declare both variables mut", "cast explicitly: a as f64 + b", "use the ++ operator"]', 2, 'Rust does not mix numeric types automatically — conversion is always explicit.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 9, 3, 'How does b = a for a String in Rust differ from b = a for a list in Python?', '["it does not", "in Rust it creates a deep copy", "in Rust a and b point to the same object", "in Rust it moves ownership, and a becomes unusable"]', 3, 'Python copies the reference, and both names see one object. Rust moves the value so that there are never two owners.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 9, 4, 'What happens with very deep recursion in Rust?', '["stack overflow — abnormal termination", "a RecursionError that can be caught", "the program slows down but keeps going", "the compiler replaces the recursion with a loop"]', 0, 'The main thread has ~8 MB of stack; on overflow the program terminates abnormally. Deep traversals are better written as a loop.');
